$relationship_definitions$::jsonb)
  loop
    if exists (select 1 from app.assessment_versions av
               where av.id = (d->>'id')::uuid and av.content_hash <> d->>'contentHash') then
      raise exception 'Refusing to overwrite published intimacy questionnaire %', d->>'id';
    end if;
    insert into app.assessment_versions (
      id,definition_key,definition_version,instrument_locale,translation_version,
      definition,questions,answer_schema,scoring_key,scoring_version,result_schema,
      timeframe,source_metadata,content_hash
    ) values (
      (d->>'id')::uuid,d->>'key',d->>'version',d->>'instrumentLocale',d->>'translationVersion',
      d,d->'questions','{"type":"integer","minimum":0,"maximum":4}'::jsonb,
      d->>'scoringKey',d->>'scoringVersion','{"version":"v1"}'::jsonb,
      d->>'timeframe',d->'source',d->>'contentHash'
    ) on conflict (id) do nothing;
  end loop;
